#!/bin/bash
sed -i 's/<p className="font-bold text-slate-900">#ORD-{order.id.slice(0, 8).toUpperCase()}<\/p>/<p className="font-bold text-slate-900">#ORD-{order.id.slice(0, 8).toUpperCase()}<\/p>\n                      {order.estimatedDeliveryDate \&\& order.status !== '\''DELIVERED'\'' \&\& <p className="text-sm font-bold text-indigo-600 mt-1">Delivery by {new Date(order.estimatedDeliveryDate).toLocaleDateString('\''en-GB'\'', {day: '\''numeric'\'', month: '\''short'\''})}<\/p>}\n                      {order.deliveredAt \&\& order.status === '\''DELIVERED'\'' \&\& <p className="text-sm font-bold text-emerald-600 mt-1">Delivered on {new Date(order.deliveredAt).toLocaleDateString('\''en-GB'\'', {day: '\''numeric'\'', month: '\''short'\''})}<\/p>}/g' src/pages/store/MyOrders.tsx
